/** 섀도 실행(집 쪽 도우미 단계): 주 모델이 이미 결정한 항목을 같은 입력으로 다시 보고 비교만 한다 — 결과로 행동하지 않는다. */
export const modelHelperShadowRuns = pgTable('model_helper_shadow_runs', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  assignmentId: varchar('assignment_id', { length: 120 }).notNull(),
  evidenceKey: varchar('evidence_key', { length: 64 }).notNull(),
  stage: varchar('stage', { length: 8 }).$type<HelperStage>().notNull(),
  candidateId: integer('candidate_id').notNull(),
  secondReviewId: integer('second_review_id'),
  /** ai1: attempt id, ai2: vote id */
  primaryRef: bigint('primary_ref', { mode: 'number' }).notNull(),
  primaryModel: varchar('primary_model', { length: 200 }).notNull(),
  primaryDecision: varchar('primary_decision', { length: 16 }).notNull(),
  primaryConfidence: doublePrecision('primary_confidence'),
  inputHash: varchar('input_hash', { length: 64 }).notNull(),
  sourceRevisionHash: varchar('source_revision_hash', { length: 64 }).notNull(),
  policyHash: varchar('policy_hash', { length: 64 }).notNull(),
  promptVersion: varchar('prompt_version', { length: 40 }).notNull(),
  rulesVersion: varchar('rules_version', { length: 40 }).notNull(),
  state: varchar('state', { length: 10 }).$type<HelperShadowRunState>().notNull(),
  helperDecision: varchar('helper_decision', { length: 16 }),
  helperConfidence: doublePrecision('helper_confidence'),
  helperOutcome: jsonb('helper_outcome').$type<Record<string, unknown>>(),
  agreement: varchar('agreement', { length: 32 }).$type<HelperShadowAgreement>(),
  errorCode: varchar('error_code', { length: 40 }),
  requestId: uuid('request_id'),
  latencyMs: integer('latency_ms'),
  jobToken: uuid('job_token').notNull(),
  createdAt: timestamp('created_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
  completedAt: timestamp('completed_at', { withTimezone: true, precision: 3 }),
}, table => [
  foreignKey({ columns: [table.assignmentId], foreignColumns: [modelHelperAssignments.assignmentId], name: 'model_helper_shadow_runs_assignment_fk' }).onDelete('cascade'),
  check('model_helper_shadow_runs_stage_check', sql`${table.stage} IN ('ai1','ai2')`),
  check('model_helper_shadow_runs_state_check', sql`${table.state} IN ('claimed','succeeded','failed','unknown','cancelled')`),
  check('model_helper_shadow_runs_outcome_check', sql`${table.helperOutcome} IS NULL OR pg_column_size(${table.helperOutcome}) <= 16384`),
  check('model_helper_shadow_runs_agreement_check', sql`${table.agreement} IN ('same','helper_approve_primary_reject','helper_reject_primary_approve','helper_abstain','primary_abstain','other')`),
  unique('model_helper_shadow_runs_sample_key').on(table.assignmentId, table.evidenceKey, table.candidateId, table.inputHash),
  index('model_helper_shadow_runs_evidence_idx').on(table.assignmentId, table.evidenceKey, table.createdAt.desc()),
]);
/** 실전 도우미 출력과 그 하류 결과(AI2 일치·불일치, 사람 뒤집음)의 연결. attempt_id(ai1) 또는 second_review_id(ai2) 하나만. */
export const modelHelperLiveOutputs = pgTable('model_helper_live_outputs', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  assignmentId: varchar('assignment_id', { length: 120 }).notNull(),
  assignmentVersion: bigint('assignment_version', { mode: 'number' }).notNull(),
  evidenceKey: varchar('evidence_key', { length: 64 }).notNull(),
  stage: varchar('stage', { length: 8 }).$type<HelperStage>().notNull(),
  candidateId: integer('candidate_id').notNull(),
  attemptId: integer('attempt_id'),
  secondReviewId: integer('second_review_id'),
  helperDecision: varchar('helper_decision', { length: 16 }),
  downstream: varchar('downstream', { length: 20 }).$type<HelperLiveDownstream>(),
  downstreamAt: timestamp('downstream_at', { withTimezone: true, precision: 3 }),
  createdAt: timestamp('created_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
}, table => [
  check('model_helper_live_outputs_stage_check', sql`${table.stage} IN ('ai1','ai2')`),
  check('model_helper_live_outputs_downstream_check', sql`${table.downstream} IN ('ai2_agreed','ai2_disagreed','human_overturned','none')`),
  check('model_helper_live_outputs_ref_check', sql`(${table.attemptId} IS NULL) <> (${table.secondReviewId} IS NULL)`),
  index('model_helper_live_outputs_assignment_idx').on(table.assignmentId, table.createdAt.desc()),
]);

export const operationsObservations = pgTable('operations_observations', {
  key: varchar('key', { length: 80 }).primaryKey(),
  value: jsonb('value').$type<Record<string, unknown>>().notNull(),
  observedAt: timestamp('observed_at').notNull().defaultNow(),
});
export const categoryDecisions = pgTable('category_decisions', {
  repo: varchar('repo', { length: 200 }).primaryKey(),
  sourceHash: varchar('source_hash', { length: 64 }).notNull(),
  category: varchar('category', { length: 40 }),
  reason: text('reason').notNull(),
  actor: varchar('actor', { length: 120 }).notNull(),
  revision: integer('revision').notNull().default(1),
  retryAt: timestamp('retry_at').notNull(),
  updatedAt: timestamp('updated_at').notNull().defaultNow(),
});
/**
 * 관리자 작업 로그. 덧붙이기만 한다 — 고치기·지우기·비우기는 DB 트리거가 거부한다(0056).
 * 스크립트가 남긴 옛 행은 actor_kind·ip 가 비어 있다.
 */
export const operationsAudit = pgTable('operations_audit', {
  id: serial('id').primaryKey(), actor: varchar('actor', { length: 120 }).notNull(),
  action: varchar('action', { length: 80 }).notNull(), target: varchar('target', { length: 200 }).notNull(),
  detail: jsonb('detail').$type<Record<string, unknown>>().notNull(),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  /** 'github' | 'local' | 'token' */
  actorKind: varchar('actor_kind', { length: 12 }),
  ip: varchar('ip', { length: 64 }),
  userAgent: varchar('user_agent', { length: 300 }),
  ok: boolean('ok').notNull().default(true),
  error: varchar('error', { length: 300 }),
}, (table) => [index('operations_audit_action_created_idx').on(table.action, table.createdAt.desc())]);

/** Collector PATs are encrypted with a dedicated secret shared by web and crawler instances. */
export const githubCollectorAccounts = pgTable('github_collector_accounts', {
  userId: bigint('user_id', { mode: 'number' }).primaryKey(),
  login: varchar('login', { length: 100 }).notNull(),
  encryptedToken: text('encrypted_token').notNull(),
  enabled: boolean('enabled').notNull().default(true),
  coreQuota: jsonb('core_quota').$type<{ limit: number; used: number; remaining: number; reset: number }>(),
  quotaObservedAt: timestamp('quota_observed_at'),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at').notNull().defaultNow(),
});
/**
 * GitHub App 수집 자격(0064) — 설치(installation)마다 따로 한도가 있어, 같은 계정의 개인 토큰과 달리 한도가 더해진다.
 * 개인 키는 수집 비밀키(GITHUB_COLLECTOR_SECRET)로 암호화해 두고, 워커가 한 시간짜리 설치 토큰을 만들어 쓴다(github-apps.ts).
 */
export const githubCollectorApps = pgTable('github_collector_apps', {
  installationId: bigint('installation_id', { mode: 'number' }).primaryKey(),
  appId: bigint('app_id', { mode: 'number' }).notNull(),
  appSlug: varchar('app_slug', { length: 100 }).notNull(),
  accountLogin: varchar('account_login', { length: 100 }).notNull(),
  encryptedPrivateKey: text('encrypted_private_key').notNull(),
  enabled: boolean('enabled').notNull().default(true),
  coreQuota: jsonb('core_quota').$type<{ limit: number; used: number; remaining: number; reset: number }>(),
  quotaObservedAt: timestamp('quota_observed_at'),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at').notNull().defaultNow(),
  /**
   * 이 설치를 읽을 수 있는 Oracle 계정(nomorevibe_oracle_*) 이름(0106). RLS 가 Oracle 계정의 행을 여기에 든 설치로 좁힌다 — 다른 서버 몫
   * 설치의 개인 키 암호문을 읽지 못한다. 운영자가 Oracle 계정을 만들 때 넣는다. 관리자 등록(upsert)은 이 열을 바꾸지 않는다.
   */
  oraclePrincipals: text('oracle_principals').array().notNull().default(sql`'{}'`),
});

/** Additive, disabled by default. A draining transition changes no live job/item owner. */
export const jobBatchControl = pgTable('job_batch_control', {
  id: integer('id').primaryKey().notNull(),
  mode: varchar('mode', { length: 12 }).$type<'legacy' | 'draining' | 'versioned'>().notNull().default('legacy'),
  drainingFrom: varchar('draining_from', { length: 12 }).$type<'legacy' | 'versioned'>(),
  epoch: bigint('epoch', { mode: 'number' }).notNull().default(1),
  writerContractVersion: integer('writer_contract_version').notNull().default(0),
  policy: jsonb('policy'), policyHash: varchar('policy_hash', { length: 64 }),
  updatedAt: timestamp('updated_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
},table=>[
  check('job_batch_control_id_check',sql`${table.id}=1`),
  check('job_batch_control_mode_check',sql`${table.mode} IN ('legacy','draining','versioned')`),
  check('job_batch_control_epoch_check',sql`${table.epoch} BETWEEN 1 AND 9007199254740991`),
  check('job_batch_control_writer_contract_version_check',sql`${table.writerContractVersion}>=0`),
  check('job_batch_control_drain_check',sql`(${table.mode}='draining' AND ${table.drainingFrom} IS NOT NULL AND ${table.drainingFrom} IN ('legacy','versioned')) OR (${table.mode}<>'draining' AND ${table.drainingFrom} IS NULL)`),
  check('job_batch_control_policy_check',sql`(${table.policy} IS NULL AND ${table.policyHash} IS NULL) OR (${table.policy} IS NOT NULL AND ${table.policyHash} IS NOT NULL AND ${table.policyHash} ~ '^[0-9a-f]{64}$')`),
]);
export const jobBatchCandidates = pgTable('job_batch_candidates', {
  role: varchar('role', { length: 30 }).notNull(), instanceId: varchar('instance_id', { length: 48 }).notNull(),
  host: varchar('host', { length: 24 }).notNull(), bootId: varchar('boot_id', { length: 36 }).notNull(),
  release: varchar('release', { length: 120 }).notNull(), policyHash: varchar('policy_hash', { length: 64 }).notNull(),
  capability: jsonb('capability'), resultEvidence: jsonb('result_evidence'),
  observedAt: timestamp('observed_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
}, table => [primaryKey({columns:[table.role,table.instanceId]}),
  check('job_batch_candidates_role_check',sql`(${table.role} IN ('crawler','reviewer','publisher','text','maintenance','translation','product-health','site-evidence','official-news')) OR ${table.role} = 'scheduler'`),
  check('job_batch_candidates_host_check',sql`${table.host} IN ('m3','mini','oracle-osaka-smoke')`),
  check('job_batch_candidates_policy_hash_check',sql`${table.policyHash} ~ '^[0-9a-f]{64}$'`),
]);

/**
 * Admin-managed gateway serving contracts (0147). The enabled row is the only source of a route+model contract (no env contracts since 2026-10-31).
 * The contract JSON is validated by the route schema in the app; the API key is encrypted (lib/security/secret-box) and never part of it.
 */
export const modelServingContracts = pgTable('model_serving_contracts', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  routeId: varchar('route_id', { length: 64 }).notNull(),
  model: varchar('model', { length: 200 }).notNull(),
  contract: jsonb('contract').$type<Record<string, unknown>>().notNull(),
  contractHash: varchar('contract_hash', { length: 64 }).notNull(),
  auth: varchar('auth', { length: 16 }).$type<'gateway' | 'none' | 'stored'>().notNull().default('gateway'),
  apiKeyCiphertext: text('api_key_ciphertext'),
  /** 'direct' = the endpoint is the engine itself (0148); the gateway-only terminal rules then do not apply. */
  transport: varchar('transport', { length: 16 }).$type<'gateway' | 'direct'>().notNull().default('gateway'),
  enabled: boolean('enabled').notNull().default(true),
  note: varchar('note', { length: 400 }),
  updatedBy: varchar('updated_by', { length: 120 }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
  updatedAt: timestamp('updated_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
}, table => [
  check('model_serving_contracts_identity_check', sql`jsonb_typeof(${table.contract}) = 'object' AND ${table.contract}->>'routeId' = ${table.routeId} AND ${table.contract}->>'model' = ${table.model}`),
  check('model_serving_contracts_hash_check', sql`${table.contractHash} ~ '^[a-f0-9]{64}$'`),
  check('model_serving_contracts_auth_check', sql`${table.auth} IN ('gateway','none','stored') AND (${table.auth} = 'stored') = (${table.apiKeyCiphertext} IS NOT NULL)`),
  check('model_serving_contracts_transport_check', sql`${table.transport} IN ('gateway','direct')`),
  uniqueIndex('model_serving_contracts_enabled_idx').on(table.routeId, table.model).where(sql`${table.enabled}`),
]);

/** Admin overrides of the code-default model registry (0148). An enabled row replaces the definition of the same key. */
export const modelRegistryOverrides = pgTable('model_registry_overrides', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  key: varchar('key', { length: 120 }).notNull(),
  definition: jsonb('definition').$type<Record<string, unknown>>().notNull(),
  enabled: boolean('enabled').notNull().default(true),
  note: varchar('note', { length: 400 }),
  updatedBy: varchar('updated_by', { length: 120 }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
  updatedAt: timestamp('updated_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
}, table => [
  check('model_registry_overrides_identity_check', sql`jsonb_typeof(${table.definition}) = 'object' AND ${table.definition}->>'key' = ${table.key}`),
  uniqueIndex('model_registry_overrides_enabled_idx').on(table.key).where(sql`${table.enabled}`),
]);

/**
 * 관리자 실시간 한도 문서(0152): 경로 한도(limits/timeouts/deadlines)·번역 묶음·틱 예산. 한 행(id = 1), 코드 기본값 위에 덮는 sparse JSON
 * (lib/operations/runtime-settings-schema.ts). 판 = storedSettingsVersion(values); revision 은 폼의 compare-and-set 과 감사 기록의 참조다.
 * 이력 표는 없다 — operations_audit(runtime-settings-save) 가 저장마다 before/after/changes/revision 을 남긴다.
 */
export const runtimeSettings = pgTable('runtime_settings', {
  id: integer('id').primaryKey().default(1),
  values: jsonb('values').$type<Record<string, unknown>>().notNull(),
  revision: bigint('revision', { mode: 'number' }).notNull().default(1),
  updatedBy: varchar('updated_by', { length: 120 }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
  updatedAt: timestamp('updated_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
}, table => [
  check('runtime_settings_single_row_check', sql`${table.id} = 1`),
  // coalesce: a document without version must fail the CHECK (a NULL comparison would pass it)
  check('runtime_settings_values_check', sql`jsonb_typeof(${table.values}) = 'object' AND coalesce(${table.values}->>'version', '') = '1' AND pg_column_size(${table.values}) <= 65536`),
  check('runtime_settings_revision_check', sql`${table.revision} BETWEEN 1 AND 9007199254740991`),
]);

/** 마지막 GET {base_url}/models 결과 한 줄(0162). maxModelLen 은 엔진이 알려 줄 때만(mlx_lm.server 등은 없다). */
export type AiConnectionModel = { id: string; maxModelLen: number | null };
/** 연결별 덧붙임(0162). contextTokens = /models 가 최대 길이를 주지 않는 모델의 운영자 입력 상한(토큰). */
export type AiConnectionOptions = { contextTokens?: number };

/**
 * AI 연결(0162, 2026-11-02 작업 ↔ 모델 순위 설계 PR A). 엔진 하나(OpenAI 호환 `/v1` 주소 + 선택 키) 또는 CLI 도구 하나(claude·codex·grok + 운영자가 적은 모델 이름).
 * 서버 목록은 코드에 없다 — 운영자가 여기 저장한 것만 연결이다. 키는 secret-box 암호문(AAD = aiConnectionKeyAad(id))이고 화면·감사에 다시 나가지 않는다.
 * device_id 는 용량 장비(model_capacity_devices) 이름이다. 이 판에서는 잡이 이 표를 읽지 않는다(PR B 부터).
 */
export const aiConnections = pgTable('ai_connections', {
  id: uuid('id').primaryKey(),
  label: varchar('label', { length: 80 }).notNull(),
  kind: varchar('kind', { length: 8 }).$type<'api' | 'cli'>().notNull(),
  baseUrl: varchar('base_url', { length: 400 }),
  apiKeyCiphertext: text('api_key_ciphertext'),
  cliTool: varchar('cli_tool', { length: 16 }).$type<'claude' | 'codex' | 'grok' | 'opencode'>(),
  cliModels: text('cli_models').array().notNull().default(sql`'{}'::text[]`),
  models: jsonb('models').$type<AiConnectionModel[]>(),
  modelsReadAt: timestamp('models_read_at', { withTimezone: true, precision: 3 }),
  modelsError: varchar('models_error', { length: 200 }),
  deviceId: varchar('device_id', { length: 120 }).notNull(),
  capacitySlots: integer('capacity_slots').notNull().default(1),
  options: jsonb('options').$type<AiConnectionOptions>().notNull().default(sql`'{}'::jsonb`),
  enabled: boolean('enabled').notNull().default(true),
  version: bigint('version', { mode: 'number' }).notNull().default(1),
  note: varchar('note', { length: 400 }),
  updatedBy: varchar('updated_by', { length: 120 }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
  updatedAt: timestamp('updated_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
}, table => [
  check('ai_connections_kind_check', sql`${table.kind} IN ('api','cli')`),
  check('ai_connections_label_check', sql`char_length(${table.label}) BETWEEN 1 AND 80 AND ${table.label} = btrim(${table.label}) AND ${table.label} !~ '[[:cntrl:]]'`),
  check('ai_connections_api_check', sql`${table.kind} <> 'api' OR (${table.baseUrl} IS NOT NULL AND ${table.cliTool} IS NULL AND cardinality(${table.cliModels}) = 0)`),
  check('ai_connections_cli_check', sql`${table.kind} <> 'cli' OR (${table.cliTool} IN ('claude','codex','grok','opencode') AND ((${table.baseUrl} IS NULL AND ${table.apiKeyCiphertext} IS NULL) OR (${table.cliTool} = 'opencode' AND ${table.baseUrl} IS NOT NULL AND ${table.apiKeyCiphertext} IS NOT NULL)) AND cardinality(${table.cliModels}) BETWEEN 1 AND CASE WHEN ${table.cliTool} = 'opencode' THEN 512 ELSE 32 END AND array_position(${table.cliModels}, NULL) IS NULL AND ${table.models} IS NULL AND ${table.modelsReadAt} IS NULL AND ${table.modelsError} IS NULL)`),
  check('ai_connections_base_url_check', sql`${table.baseUrl} IS NULL OR ${table.baseUrl} ~ '^https?://[^/?#@[:space:][:cntrl:]]+/v1$'`),
  check('ai_connections_models_check', sql`${table.models} IS NULL OR (jsonb_typeof(${table.models}) = 'array' AND jsonb_array_length(${table.models}) <= 512 AND pg_column_size(${table.models}) <= 131072)`),
  check('ai_connections_device_check', sql`char_length(${table.deviceId}) BETWEEN 1 AND 120 AND ${table.deviceId} = btrim(${table.deviceId}) AND ${table.deviceId} !~ '[[:cntrl:]]'`),
  check('ai_connections_slots_check', sql`${table.capacitySlots} BETWEEN 1 AND 256`),
  check('ai_connections_options_check', sql`jsonb_typeof(${table.options}) = 'object' AND pg_column_size(${table.options}) <= 8192`),
  check('ai_connections_version_check', sql`${table.version} BETWEEN 1 AND 9007199254740991`),
  uniqueIndex('ai_connections_label_idx').on(sql`lower(${table.label})`),
  uniqueIndex('ai_connections_base_url_idx').on(table.baseUrl).where(sql`${table.baseUrl} IS NOT NULL`),
]);

/**
 * 작업 ↔ 모델 순위(0162). (작업, 칸, 순위) 하나에 (연결, 모델) 하나 — 1순위를 먼저 쓰고, 쓸 수 없으면 2·3순위. 칸(slot)은 2차 투표자 1·2·3처럼 한 작업 안의
 * 나란한 자리이고 다른 작업은 1이다. 작업 이름·칸 수·받는 연결 종류는 코드 목록(lib/llm/ai-tasks.ts)이 정한다. 이 판에서는 잡이 읽지 않는다(PR B 부터).
 */
export const aiTaskModels = pgTable('ai_task_models', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  task: varchar('task', { length: 64 }).notNull(),
  slot: integer('slot').notNull().default(1),
  rank: integer('rank').notNull(),
  connectionId: uuid('connection_id').notNull(),
  model: varchar('model', { length: 200 }).notNull(),
  options: jsonb('options').$type<Record<string, unknown>>().notNull().default(sql`'{}'::jsonb`),
  enabled: boolean('enabled').notNull().default(true),
  note: varchar('note', { length: 400 }),
  updatedBy: varchar('updated_by', { length: 120 }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
  updatedAt: timestamp('updated_at', { withTimezone: true, precision: 3 }).notNull().default(sql`clock_timestamp()`),
}, table => [
  foreignKey({ columns: [table.connectionId], foreignColumns: [aiConnections.id], name: 'ai_task_models_connection_fk' }).onDelete('restrict'),
  check('ai_task_models_task_check', sql`${table.task} ~ '^[a-z0-9][a-z0-9-]{0,63}$'`),
  check('ai_task_models_slot_check', sql`${table.slot} BETWEEN 1 AND 8`),
  check('ai_task_models_rank_check', sql`${table.rank} BETWEEN 1 AND 3`),
  check('ai_task_models_model_check', sql`char_length(${table.model}) BETWEEN 1 AND 200 AND ${table.model} = btrim(${table.model}) AND ${table.model} !~ '[[:cntrl:]]'`),
  check('ai_task_models_options_check', sql`jsonb_typeof(${table.options}) = 'object' AND pg_column_size(${table.options}) <= 4096`),
  unique('ai_task_models_rank_key').on(table.task, table.slot, table.rank),
  unique('ai_task_models_model_key').on(table.task, table.slot, table.connectionId, table.model),
  index('ai_task_models_connection_idx').on(table.connectionId),
]);
